mkitem!{mktrait!{# [doc = " An implementation of `Allocator` can allocate, grow, shrink, and deallocate arbitrary blocks of"] # [doc = " data described via [`Layout`][]."] # [doc = ""] # [doc = " `Allocator` is designed to be implemented on ZSTs, references, or smart pointers."] # [doc = " An allocator for `MyAlloc([u8; N])` cannot be moved, without updating the pointers to the"] # [doc = " allocated memory."] # [doc = ""] # [doc = " In contrast to [`GlobalAlloc`][], `Allocator` allows zero-sized allocations. If an underlying"] # [doc = " allocator does not support this (like jemalloc) or responds by returning a null pointer"] # [doc = " (such as `libc::malloc`), this must be caught by the implementation."] # [doc = ""] # [doc = " ### Currently allocated memory"] # [doc = ""] # [doc = " Some of the methods require that a memory block is *currently allocated* by an allocator."] # [doc = " This means that:"] # [doc = "  * the starting address for that memory block was previously"] # [doc = "    returned by [`allocate`], [`grow`], or [`shrink`], and"] # [doc = "  * the memory block has not subsequently been deallocated."] # [doc = ""] # [doc = " A memory block is deallocated by a call to [`deallocate`],"] # [doc = " or by a call to [`grow`] or [`shrink`] that returns `Ok`."] # [doc = " A call to `grow` or `shrink` that returns `Err`,"] # [doc = " does not deallocate the memory block passed to it."] # [doc = ""] # [doc = " [`allocate`]: Allocator::allocate"] # [doc = " [`grow`]: Allocator::grow"] # [doc = " [`shrink`]: Allocator::shrink"] # [doc = " [`deallocate`]: Allocator::deallocate"] # [doc = ""] # [doc = " ### Memory fitting"] # [doc = ""] # [doc = " Some of the methods require that a `layout` *fit* a memory block or vice versa. This means that the"] # [doc = " following conditions must hold:"] # [doc = "  * the memory block must be *currently allocated* with alignment of [`layout.align()`], and"] # [doc = "  * [`layout.size()`] must fall in the range `min ..= max`, where:"] # [doc = "    - `min` is the size of the layout used to allocate the block, and"] # [doc = "    - `max` is the actual size returned from [`allocate`], [`grow`], or [`shrink`]."] # [doc = ""] # [doc = " [`layout.align()`]: Layout::align"] # [doc = " [`layout.size()`]: Layout::size"] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Memory blocks that are [*currently allocated*] by an allocator,"] # [doc = " must point to valid memory, and retain their validity until either:"] # [doc = "  - the memory block is deallocated, or"] # [doc = "  - the allocator is dropped."] # [doc = ""] # [doc = " Copying, cloning, or moving the allocator must not invalidate memory blocks returned from it."] # [doc = " A copied or cloned allocator must behave like the original allocator."] # [doc = ""] # [doc = " A memory block which is [*currently allocated*] may be passed to"] # [doc = " any method of the allocator that accepts such an argument."] # [doc = ""] # [doc = " [*currently allocated*]: #currently-allocated-memory"] # [unstable (feature = "allocator_api" , issue = "32838")] pub unsafe trait Allocator { # [doc = " Attempts to allocate a block of memory."] # [doc = ""] # [doc = " On success, returns a [`NonNull<[u8]>`][NonNull] meeting the size and alignment guarantees of `layout`."] # [doc = ""] # [doc = " The returned block may have a larger size than specified by `layout.size()`, and may or may"] # [doc = " not have its contents initialized."] # [doc = ""] # [doc = " The returned block of memory remains valid as long as it is [*currently allocated*] and the shorter of:"] # [doc = "   - the borrow-checker lifetime of the allocator type itself."] # [doc = "   - as long as the allocator and all its clones have not been dropped."] # [doc = ""] # [doc = " [*currently allocated*]: #currently-allocated-memory"] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " Returning `Err` indicates that either memory is exhausted or `layout` does not meet"] # [doc = " allocator's size or alignment constraints."] # [doc = ""] # [doc = " Implementations are encouraged to return `Err` on memory exhaustion rather than panicking or"] # [doc = " aborting, but this is not a strict requirement. (Specifically: it is *legal* to implement"] # [doc = " this trait atop an underlying native allocation library that aborts on memory exhaustion.)"] # [doc = ""] # [doc = " Clients wishing to abort computation in response to an allocation error are encouraged to"] # [doc = " call the [`handle_alloc_error`] function, rather than directly invoking `panic!` or similar."] # [doc = ""] # [doc = " [`handle_alloc_error`]: ../../alloc/alloc/fn.handle_alloc_error.html"] fn allocate (& self , layout : Layout) -> Result < NonNull < [u8] > , AllocError > ; # [doc = " Behaves like `allocate`, but also ensures that the returned memory is zero-initialized."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " Returning `Err` indicates that either memory is exhausted or `layout` does not meet"] # [doc = " allocator's size or alignment constraints."] # [doc = ""] # [doc = " Implementations are encouraged to return `Err` on memory exhaustion rather than panicking or"] # [doc = " aborting, but this is not a strict requirement. (Specifically: it is *legal* to implement"] # [doc = " this trait atop an underlying native allocation library that aborts on memory exhaustion.)"] # [doc = ""] # [doc = " Clients wishing to abort computation in response to an allocation error are encouraged to"] # [doc = " call the [`handle_alloc_error`] function, rather than directly invoking `panic!` or similar."] # [doc = ""] # [doc = " [`handle_alloc_error`]: ../../alloc/alloc/fn.handle_alloc_error.html"] fn allocate_zeroed (& self , layout : Layout) -> Result < NonNull < [u8] > , AllocError > { let ptr = self . allocate (layout) ? ; unsafe { ptr . as_non_null_ptr () . as_ptr () . write_bytes (0 , ptr . len ()) } Ok (ptr) } # [doc = " Deallocates the memory referenced by `ptr`."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " * `ptr` must denote a block of memory [*currently allocated*] via this allocator, and"] # [doc = " * `layout` must [*fit*] that block of memory."] # [doc = ""] # [doc = " [*currently allocated*]: #currently-allocated-memory"] # [doc = " [*fit*]: #memory-fitting"] unsafe fn deallocate (& self , ptr : NonNull < u8 > , layout : Layout) ; # [doc = " Attempts to extend the memory block."] # [doc = ""] # [doc = " Returns a new [`NonNull<[u8]>`][NonNull] containing a pointer and the actual size of the allocated"] # [doc = " memory. The pointer is suitable for holding data described by `new_layout`. To accomplish"] # [doc = " this, the allocator may extend the allocation referenced by `ptr` to fit the new layout."] # [doc = ""] # [doc = " If this returns `Ok`, then ownership of the memory block referenced by `ptr` has been"] # [doc = " transferred to this allocator. Any access to the old `ptr` is Undefined Behavior, even if the"] # [doc = " allocation was grown in-place. The newly returned pointer is the only valid pointer"] # [doc = " for accessing this memory now."] # [doc = ""] # [doc = " If this method returns `Err`, then ownership of the memory block has not been transferred to"] # [doc = " this allocator, and the contents of the memory block are unaltered."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " * `ptr` must denote a block of memory [*currently allocated*] via this allocator."] # [doc = " * `old_layout` must [*fit*] that block of memory (The `new_layout` argument need not fit it.)."] # [doc = " * `new_layout.size()` must be greater than or equal to `old_layout.size()`."] # [doc = ""] # [doc = " Note that `new_layout.align()` need not be the same as `old_layout.align()`."] # [doc = ""] # [doc = " [*currently allocated*]: #currently-allocated-memory"] # [doc = " [*fit*]: #memory-fitting"] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " Returns `Err` if the new layout does not meet the allocator's size and alignment"] # [doc = " constraints of the allocator, or if growing otherwise fails."] # [doc = ""] # [doc = " Implementations are encouraged to return `Err` on memory exhaustion rather than panicking or"] # [doc = " aborting, but this is not a strict requirement. (Specifically: it is *legal* to implement"] # [doc = " this trait atop an underlying native allocation library that aborts on memory exhaustion.)"] # [doc = ""] # [doc = " Clients wishing to abort computation in response to an allocation error are encouraged to"] # [doc = " call the [`handle_alloc_error`] function, rather than directly invoking `panic!` or similar."] # [doc = ""] # [doc = " [`handle_alloc_error`]: ../../alloc/alloc/fn.handle_alloc_error.html"] unsafe fn grow (& self , ptr : NonNull < u8 > , old_layout : Layout , new_layout : Layout ,) -> Result < NonNull < [u8] > , AllocError > { debug_assert ! (new_layout . size () >= old_layout . size () , "`new_layout.size()` must be greater than or equal to `old_layout.size()`") ; let new_ptr = self . allocate (new_layout) ? ; unsafe { ptr :: copy_nonoverlapping (ptr . as_ptr () , new_ptr . as_mut_ptr () , old_layout . size ()) ; self . deallocate (ptr , old_layout) ; } Ok (new_ptr) } # [doc = " Behaves like `grow`, but also ensures that the new contents are set to zero before being"] # [doc = " returned."] # [doc = ""] # [doc = " The memory block will contain the following contents after a successful call to"] # [doc = " `grow_zeroed`:"] # [doc = "   * Bytes `0..old_layout.size()` are preserved from the original allocation."] # [doc = "   * Bytes `old_layout.size()..old_size` will either be preserved or zeroed, depending on"] # [doc = "     the allocator implementation. `old_size` refers to the size of the memory block prior"] # [doc = "     to the `grow_zeroed` call, which may be larger than the size that was originally"] # [doc = "     requested when it was allocated."] # [doc = "   * Bytes `old_size..new_size` are zeroed. `new_size` refers to the size of the memory"] # [doc = "     block returned by the `grow_zeroed` call."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " * `ptr` must denote a block of memory [*currently allocated*] via this allocator."] # [doc = " * `old_layout` must [*fit*] that block of memory (The `new_layout` argument need not fit it.)."] # [doc = " * `new_layout.size()` must be greater than or equal to `old_layout.size()`."] # [doc = ""] # [doc = " Note that `new_layout.align()` need not be the same as `old_layout.align()`."] # [doc = ""] # [doc = " [*currently allocated*]: #currently-allocated-memory"] # [doc = " [*fit*]: #memory-fitting"] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " Returns `Err` if the new layout does not meet the allocator's size and alignment"] # [doc = " constraints of the allocator, or if growing otherwise fails."] # [doc = ""] # [doc = " Implementations are encouraged to return `Err` on memory exhaustion rather than panicking or"] # [doc = " aborting, but this is not a strict requirement. (Specifically: it is *legal* to implement"] # [doc = " this trait atop an underlying native allocation library that aborts on memory exhaustion.)"] # [doc = ""] # [doc = " Clients wishing to abort computation in response to an allocation error are encouraged to"] # [doc = " call the [`handle_alloc_error`] function, rather than directly invoking `panic!` or similar."] # [doc = ""] # [doc = " [`handle_alloc_error`]: ../../alloc/alloc/fn.handle_alloc_error.html"] unsafe fn grow_zeroed (& self , ptr : NonNull < u8 > , old_layout : Layout , new_layout : Layout ,) -> Result < NonNull < [u8] > , AllocError > { debug_assert ! (new_layout . size () >= old_layout . size () , "`new_layout.size()` must be greater than or equal to `old_layout.size()`") ; let new_ptr = self . allocate_zeroed (new_layout) ? ; unsafe { ptr :: copy_nonoverlapping (ptr . as_ptr () , new_ptr . as_mut_ptr () , old_layout . size ()) ; self . deallocate (ptr , old_layout) ; } Ok (new_ptr) } # [doc = " Attempts to shrink the memory block."] # [doc = ""] # [doc = " Returns a new [`NonNull<[u8]>`][NonNull] containing a pointer and the actual size of the allocated"] # [doc = " memory. The pointer is suitable for holding data described by `new_layout`. To accomplish"] # [doc = " this, the allocator may shrink the allocation referenced by `ptr` to fit the new layout."] # [doc = ""] # [doc = " If this returns `Ok`, then ownership of the memory block referenced by `ptr` has been"] # [doc = " transferred to this allocator. Any access to the old `ptr` is Undefined Behavior, even if the"] # [doc = " allocation was shrunk in-place. The newly returned pointer is the only valid pointer"] # [doc = " for accessing this memory now."] # [doc = ""] # [doc = " If this method returns `Err`, then ownership of the memory block has not been transferred to"] # [doc = " this allocator, and the contents of the memory block are unaltered."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " * `ptr` must denote a block of memory [*currently allocated*] via this allocator."] # [doc = " * `old_layout` must [*fit*] that block of memory (The `new_layout` argument need not fit it.)."] # [doc = " * `new_layout.size()` must be smaller than or equal to `old_layout.size()`."] # [doc = ""] # [doc = " Note that `new_layout.align()` need not be the same as `old_layout.align()`."] # [doc = ""] # [doc = " [*currently allocated*]: #currently-allocated-memory"] # [doc = " [*fit*]: #memory-fitting"] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " Returns `Err` if the new layout does not meet the allocator's size and alignment"] # [doc = " constraints of the allocator, or if shrinking otherwise fails."] # [doc = ""] # [doc = " Implementations are encouraged to return `Err` on memory exhaustion rather than panicking or"] # [doc = " aborting, but this is not a strict requirement. (Specifically: it is *legal* to implement"] # [doc = " this trait atop an underlying native allocation library that aborts on memory exhaustion.)"] # [doc = ""] # [doc = " Clients wishing to abort computation in response to an allocation error are encouraged to"] # [doc = " call the [`handle_alloc_error`] function, rather than directly invoking `panic!` or similar."] # [doc = ""] # [doc = " [`handle_alloc_error`]: ../../alloc/alloc/fn.handle_alloc_error.html"] unsafe fn shrink (& self , ptr : NonNull < u8 > , old_layout : Layout , new_layout : Layout ,) -> Result < NonNull < [u8] > , AllocError > { debug_assert ! (new_layout . size () <= old_layout . size () , "`new_layout.size()` must be smaller than or equal to `old_layout.size()`") ; let new_ptr = self . allocate (new_layout) ? ; unsafe { ptr :: copy_nonoverlapping (ptr . as_ptr () , new_ptr . as_mut_ptr () , new_layout . size ()) ; self . deallocate (ptr , old_layout) ; } Ok (new_ptr) } # [doc = " Creates a \"by reference\" adapter for this instance of `Allocator`."] # [doc = ""] # [doc = " The returned adapter also implements `Allocator` and will simply borrow this."] # [inline (always)] fn by_ref (& self) -> & Self where Self : Sized , { self } }}}
